    window.addEventListener('cewen:operation-error',e=>this.report((e as CustomEvent).detail));
    window.addEventListener('cewen:editing-command',e=>{if(this.root.hidden||this.home)return;const cmd=(e as CustomEvent<string>).detail;if(!['save','undo','redo'].includes(cmd))return;if(cmd!=='save'&&(document.activeElement as HTMLElement)?.closest('input,textarea,[contenteditable=true]'))return;e.preventDefault();if(cmd==='save')void this.save().catch(err=>this.report(err));if(cmd==='undo')this.current()?.canvas.undo();if(cmd==='redo')this.current()?.canvas.redo();},{capture:true});
