  private saveNavigation(){if(!this.snapshot||isTransientProject(this.snapshot.project.id))return;try{localStorage.setItem('cewen-desktop-nav:'+this.snapshot.project.id,JSON.stringify({favorites:[...this.favorites],recent:this.recent,collapsed:[...this.collapsed]}));}catch{/* 偏好失效不影响公开文档。 */}}
  private loadNavigation(){this.favorites.clear();this.recent=[];this.collapsed.clear();this.navFilter='all';if(!this.snapshot||isTransientProject(this.snapshot.project.id))return;try{const state=JSON.parse(localStorage.getItem('cewen-desktop-nav:'+this.snapshot.project.id)??'{}');this.favorites=new Set(state.favorites??[]);this.recent=state.recent??[];this.collapsed=new Set(state.collapsed??[]);}catch{/* 使用当前会话的默认导航。 */}}
  async open(snapshot:ProjectSnapshot,admitted=false){if(!admitted&&this.snapshot?.project.id!==snapshot.project.id&&!await this.leave())return;const previous=this.snapshot?.project.id;this.clear();if(previous&&previous!==snapshot.project.id&&isTransientProject(previous))(await import('../browser/transient-projects')).disposeTransient(previous);this.snapshot=snapshot;this.loadNavigation();this.home=false;this.libraryHost.hidden=true;this.work.hidden=false;this.show();this.options.apply(snapshot);this.renderTree();this.updateTitle();const first=this.documents().find(d=>d.path.endsWith('/start.md'))??this.documents()[0];if(first)this.openDocument(first.id);else this.renderTabs();this.notice(isTransientProject(snapshot.project.id)?'临时示例 · 所有编辑仅存于本次会话；保存将另存为新项目。':'单击打开，双击固定标签；空白左键拖动画布，右键拖动框选。');await this.recoverDrafts();}
  /** 外部刷新只更新干净标签；有草稿的标签保留旧哈希供正式保存时判断冲突。 */
  receive(snapshot:ProjectSnapshot){if(this.snapshot?.project.id!==snapshot.project.id||this.home||snapshot.historical)return;if(isTransientProject(snapshot.project.id)&&snapshot.revision!==this.snapshot.revision)this.sessionChanged=true;this.snapshot=snapshot;for(const [id,t] of this.tabs){const doc=snapshot.documents.find(d=>d.id===id);if(doc&&!t.dirty&&!t.preset&&doc.hash!==t.baseHash){this.disposeTab(t);this.tabs.delete(id);this.mountTab(doc,t.pinned);}}this.renderTree();this.renderTabs();this.updateTitle();}
