  private updateTitle(){this.menu.querySelector('[data-project-title]')!.textContent=this.snapshot?.project.name??'';this.menu.querySelector('[data-session-kind]')!.textContent=this.snapshot&&isTransientProject(this.snapshot.project.id)?'临时会话 · 关闭不保存':'';}
