    const tab={doc:{...doc},baseText:doc.hash?doc.text:null,baseHash:doc.hash||null,baseLayoutHash:companion?.hash??null,layout:layout??{format:1,documentId:doc.id,blocks:{}},dirty:false,pinned,host,assets:[]} as unknown as DocumentTab;
