    this.tree.innerHTML=query||this.navFilter!=='all'?docs.filter(d=>match(d)&&(this.navFilter==='all'||this.navFilter==='favorites'&&this.favorites.has(d.id)||this.navFilter==='recent'&&this.recent.includes(d.id))).map(d=>row({...d,parent:undefined},0)).join(''):groups.filter(g=>!g.parent||!groups.some(p=>p.id===g.parent)).map(g=>group(g,0)).join('')+`<div class="document-tree-group" data-category=""><span>未分类</span></div>`+docs.filter(d=>(!d.system||!groups.some(g=>g.id===d.system))&&(!d.parent||!docs.some(p=>p.id===d.parent))).map(d=>row(d,0)).join('');
