    this.tree.oncontextmenu=e=>{const line=(e.target as HTMLElement).closest<HTMLElement>('[data-doc],[data-category]');if(!line)return;e.preventDefault();if(line.dataset.doc){if(!this.selected.has(line.dataset.doc))this.selected=new Set([line.dataset.doc]);this.docMenu(line.dataset.doc,line,e);}else this.categoryMenu(line.dataset.category!,line,e);};
